class HousePainter extends CustomPainter { @override void paint(Canvas canvas,Size size){final grid=Paint()..color=cyan.withValues(alpha: .07)..strokeWidth=1;for(double x=0;x<size.width;x+=22){canvas.drawLine(Offset(x,0),Offset(x,size.height),grid);}for(double y=0;y<size.height;y+=22){canvas.drawLine(Offset(0,y),Offset(size.width,y),grid);}final fill=Paint()..color=const Color(0xFF27344A);final stroke=Paint()..color=cyan.withValues(alpha: .7)..style=PaintingStyle.stroke..strokeWidth=1.6;final p=Path()..moveTo(size.width*.17,size.height*.43)..lineTo(size.width*.49,size.height*.15)..lineTo(size.width*.82,size.height*.43)..lineTo(size.width*.82,size.height*.82)..lineTo(size.width*.17,size.height*.82)..close();canvas.drawPath(p,fill);canvas.drawPath(p,stroke);final roof=Path()..moveTo(size.width*.17,size.height*.43)..lineTo(size.width*.49,size.height*.15)..lineTo(size.width*.82,size.height*.43);canvas.drawPath(roof,Paint()..color=violet..strokeWidth=3..style=PaintingStyle.stroke..strokeJoin=StrokeJoin.round);final inner=Paint()..color=cyan.withValues(alpha: .32)..style=PaintingStyle.stroke..strokeWidth=1.2;canvas.drawLine(Offset(size.width*.49,size.height*.29),Offset(size.width*.49,size.height*.82),inner);canvas.drawLine(Offset(size.width*.17,size.height*.62),Offset(size.width*.82,size.height*.62),inner);final door=Rect.fromLTWH(size.width*.43,size.height*.62,size.width*.12,size.height*.20);canvas.drawRRect(RRect.fromRectAndRadius(door,const Radius.circular(3)),Paint()..color=violet.withValues(alpha: .65));canvas.drawRRect(RRect.fromRectAndRadius(door,const Radius.circular(3)),Paint()..color=cyan..style=PaintingStyle.stroke..strokeWidth=1);} @override bool shouldRepaint(covariant CustomPainter oldDelegate)=>false;}
